<script setup>
import {ref,reactive,onMounted} from 'vue'
const props=defineProps({api:Function,context:Object}),portal=props.context.portal,roles=props.context.roles,sqe=!portal&&roles.some(r=>['SQE','superAdmin'].includes(r)),manager=!portal&&roles.some(r=>['CAT-MGR','superAdmin'].includes(r)),writer=portal&&roles.some(r=>['QUALITY','ADMIN'].includes(r))
const candidateSearch=ref('')
const tab=ref('PPAP'),rows=ref([]),total=ref(0),page=ref(1),detail=ref(null),risk=ref(null),tasks=ref([]),notices=ref([]),suppliers=ref([]),creating=ref(false),busy=ref(false),error=ref(''),notice=ref(''),attachment=ref(null),ppapItems=ref([]),selectedFiles=ref([]),comment=ref(''),assessment=ref(''),riskLevel=ref('MEDIUM'),disposition=ref('RECTIFIED'),evidence=ref(''),effectiveness=ref(''),preview=ref(null),policy=ref(null)
const form=reactive({supplierId:props.context.supplierId||'',title:'',defectKey:'',description:'',severity:'MAJOR'}),disciplines=reactive(Object.fromEntries(Array.from({length:8},(_,i)=>['D'+(i+1),'']))),source=reactive({supplierId:props.context.supplierId||'',period:new Date().toISOString().slice(0,7),mode:'SANDBOX',result:'FAIL',severity:'SEVERE'})
const labels={DRAFT:'草稿',OPEN:'待8D回复',SUBMITTED:'待SQE审核',RETURNED:'补件／重做',REJECTED:'已驳回',APPROVED:'PPAP已批准',VERIFIED:'8D已验证，待有效性确认',CLOSED:'已闭环',ESCALATED:'已升级',PENDING:'待评估',ASSESSED:'已评估',WARNING:'预警跟进中',DISPOSED:'已归档',HIGH:'高',MEDIUM:'中',LOW:'低',MINOR:'轻微',MAJOR:'主要',SEVERE:'严重',DELIVERY_EXCEPTION:'履约异常',CERTIFICATE_EXPIRED:'资质过期',COMPLIANCE_BLACKLIST:'人工合规黑名单',SCAR_OVERDUE:'8D回复超期',REPEATED_DEFECT:'重复缺陷',SEVERE_QUALITY:'严重检验不合格'}
const dnames={D1:'成立团队',D2:'问题描述',D3:'临时遏制',D4:'根因分析',D5:'选择永久纠正措施',D6:'实施并验证纠正措施',D7:'预防再发生',D8:'总结与团队认可'},text=s=>labels[s]||s,key=()=>crypto.randomUUID(),p=(path,body,method='GET',raw=false)=>props.api('/quality'+path,body,method,raw),post=(path,body={})=>p(path,body,'POST')
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function candidates(){if(!portal){const r=await props.api('/suppliers?'+new URLSearchParams({current:1,size:100,searchKey:candidateSearch.value}));suppliers.value=r.records;if(!form.supplierId)form.supplierId=r.records[0]?.id||'';if(!source.supplierId)source.supplierId=r.records[0]?.id||''}}
async function load(){if(['PPAP','SCAR'].includes(tab.value)){const d=await p('/cases?'+new URLSearchParams({kind:tab.value,current:page.value,size:20}));rows.value=d.records;total.value=d.total}else if(tab.value==='risks'){const d=await p('/risks?current='+page.value+'&size=20');rows.value=d.records;total.value=d.total}else if(tab.value==='tasks')tasks.value=await p('/tasks');else if(tab.value==='notices')notices.value=await p('/notices');else if(tab.value==='policy')policy.value=await p('/policy')}
async function selectTab(v){tab.value=v;page.value=1;detail.value=risk.value=null;creating.value=false;await load()}
async function openCase(id){detail.value=await p('/cases/'+id);risk.value=null;ppapItems.value=(detail.value.payload.items||[]).map(x=>({...x}));selectedFiles.value=detail.value.payload.fileIds||[];for(const k of Object.keys(disciplines))disciplines[k]=detail.value.payload.disciplines?.[k]||'';comment.value='';attachment.value=null}
async function refresh(){await load();if(detail.value)await openCase(detail.value.id);if(risk.value)risk.value=await p('/risks/'+risk.value.id);if(tab.value==='sources'&&preview.value)await sourcePreview()}
function create(){creating.value=true;detail.value=risk.value=null;form.title=form.description=form.defectKey='';comment.value=evidence.value=''}
async function save(){if(tab.value==='risks'){risk.value=await post('/risks',{requestKey:key(),supplierId:form.supplierId,description:form.description,evidenceRef:evidence.value});creating.value=false;await load();return}const body={requestKey:key(),supplierId:portal?props.context.supplierId:form.supplierId,title:form.title,...(tab.value==='SCAR'?{defectKey:form.defectKey,description:form.description,severity:form.severity}:{})};const d=await post(tab.value==='SCAR'?'/scars':'/ppaps',body);creating.value=false;await openCase(d.id);await load()}
async function upload(){if(!attachment.value)throw Error('请选择质量附件');const fd=new FormData();fd.append('file',attachment.value);const f=await p('/cases/'+detail.value.id+'/files',fd,'POST');ppapItems.value.push({name:f.name,fileId:f.id});selectedFiles.value.push(f.id);detail.value=await p('/cases/'+detail.value.id);attachment.value=null;notice.value='附件已私有保存'}
async function submit(){const id=detail.value.id;if(detail.value.kind==='PPAP')detail.value=await post('/cases/'+id+'/ppap-submit',{rowVersion:detail.value.rowVersion,items:ppapItems.value,comment:comment.value});else detail.value=await post('/cases/'+id+'/8d',{rowVersion:detail.value.rowVersion,disciplines:{...disciplines},fileIds:selectedFiles.value});await load()}
async function review(t,action){detail.value=await post('/cases/'+detail.value.id+'/tasks/'+t.id,{action,comment:comment.value});await load()}
async function close(){detail.value=await post('/cases/'+detail.value.id+'/close',{rowVersion:detail.value.rowVersion,effectiveness:effectiveness.value,evidenceRef:evidence.value});await load()}
async function download(id){const blob=await p('/files/'+id,undefined,'GET',true),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='quality-'+id;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function openRisk(id){risk.value=await p('/risks/'+id);assessment.value='';evidence.value='';riskLevel.value=risk.value.level||'MEDIUM'}
async function assess(){risk.value=await post('/risks/'+risk.value.id+'/assess',{rowVersion:risk.value.rowVersion,level:riskLevel.value,comment:assessment.value});await load()}
async function freeze(){risk.value=await post('/risks/'+risk.value.id+'/freeze',{rowVersion:risk.value.rowVersion,level:'HIGH',comment:assessment.value});notice.value='冻结申请已进入原审批工作台，供应商状态仍须经理审批后变更';await load()}
async function dispose(){risk.value=await post('/risks/'+risk.value.id+'/dispose',{rowVersion:risk.value.rowVersion,action:disposition.value,comment:assessment.value,evidenceRef:evidence.value});await load()}
async function sourcePreview(){preview.value=await p('/source-preview?'+new URLSearchParams({supplierId:source.supplierId,period:source.period,mode:source.mode}))}
async function demo(system){await post('/sandbox/source',{requestKey:key(),supplierId:source.supplierId,period:source.period,system,result:source.result,severity:source.severity});notice.value='本机沙箱来源已排队，经签名回写后请刷新预览；不代表真实厂商联调'}
async function publish(){await post('/source-publish',{supplierId:source.supplierId,period:source.period,mode:source.mode,basisHash:preview.value.basisHash});notice.value='已按来源快照生成绩效输入并重算；相同依据重复发布保持幂等'}
async function savePolicy(){policy.value=await post('/policy',{...policy.value,expectedVersion:policy.value.version});notice.value='新规则版本已发布；既有质量单据保留创建时响应时限，检验扣分记录保留来源版本'}
onMounted(()=>run(async()=>{await candidates();await load()}))
</script>
<template><section class="quality-panel" :aria-busy="busy"><div class="panel-heading"><div><h2>质量与风险</h2><p>PPAP提交 · SQE审核 · 8D有效性闭环 · 内部风险处置</p></div><button class="btn" :disabled="busy" @click="run(refresh)">刷新质量</button></div>
<div class="quality-actions"><button v-for="t in [{id:'PPAP',name:'PPAP资料'},{id:'SCAR',name:'SCAR / 8D'},...(!portal?[{id:'risks',name:'内部风险'}]:[]),...(sqe?[{id:'tasks',name:'SQE待办'},{id:'sources',name:'检验与绩效来源'},{id:'policy',name:'质量规则'}]:[]),{id:'notices',name:'质量通知'}]" :key="t.id" :class="['btn',{primary:tab===t.id}]" :disabled="busy" @click="run(()=>selectTab(t.id))">{{t.name}}</button></div>
<p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="info-note" role="status">{{notice}}</p>
<template v-if="['PPAP','SCAR','risks'].includes(tab)"><button v-if="tab==='PPAP'?writer:sqe" class="btn primary" :disabled="busy" @click="create">{{tab==='PPAP'?'新建PPAP':tab==='SCAR'?'发起SCAR':'登记内部合规风险'}}</button>
<form v-if="creating" class="quality-card" @submit.prevent="run(save)"><h3>{{tab==='PPAP'?'PPAP提交草稿':tab==='SCAR'?'SCAR缺陷通知':'有依据的人工合规登记'}}</h3><template v-if="!portal"><label>筛选供应商<input v-model="candidateSearch" placeholder="供应商名称或编号"/></label><button type="button" class="btn" :disabled="busy" @click="run(candidates)">查询质量供应商</button></template><label v-if="!portal">供应商<select aria-label="供应商" v-model="form.supplierId" required><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label v-if="tab!=='risks'">标题<input v-model="form.title" required maxlength="128"/></label><template v-if="tab==='SCAR'"><div class="quality-grid"><label>缺陷编码<input v-model="form.defectKey" required maxlength="80" placeholder="相同缺陷使用同一编码以跟踪复发"/></label><label>严重等级<select aria-label="严重等级" v-model="form.severity"><option value="MINOR">轻微</option><option value="MAJOR">主要</option><option value="SEVERE">严重</option></select></label></div></template><label v-if="tab!=='PPAP'">缺陷／合规事实<textarea v-model="form.description" required maxlength="2000"/></label><label v-if="tab==='risks'">证据引用<input v-model="evidence" required maxlength="500"/></label><button class="btn primary" :disabled="busy">保存质量单据</button><button type="button" class="btn" @click="creating=false">取消</button></form>
<div class="table-scroll"><table><thead><tr><th>{{tab==='risks'?'风险类型':'单据'}}</th><th>供应商</th><th>状态</th><th>{{tab==='risks'?'等级／冻结建议':'版本／截止'}}</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{tab==='risks'?text(r.riskType):r.title}}</td><td>{{r.supplierName}}</td><td>{{text(r.status)}}</td><td><template v-if="tab==='risks'"><b :class="['risk-light',r.level]">{{text(r.level)||'待评估'}}</b> {{r.freezeSuggested?'有冻结建议':''}}{{r.freezeApprovalId?'（已提交审批）':''}}</template><template v-else>第{{r.revision}}版 {{r.dueAt?new Date(Number(r.dueAt)).toLocaleString():''}}</template></td><td><button class="text-btn" :disabled="busy" @click="run(()=>tab==='risks'?openRisk(r.id):openCase(r.id))">查看{{tab==='risks'?'风险':'质量单据'}}</button></td></tr></tbody></table></div><p v-if="!rows.length" class="empty-state">当前范围暂无记录</p></template>
<article v-if="detail" class="quality-card"><div class="panel-heading"><h3>{{detail.title}} · {{text(detail.status)}}</h3><button class="btn" @click="detail=null">关闭详情</button></div><p>{{detail.kind}} · 第{{detail.revision}}版 · {{detail.defectKey||'提交物清单'}} {{detail.severity?text(detail.severity):''}}</p><p v-if="detail.meta.description">缺陷：{{detail.meta.description}}</p><p v-if="detail.dueAt">回复截止 {{new Date(Number(detail.dueAt)).toLocaleString()}} · 超时或重复缺陷生成内部风险，不自动冻结</p><p v-if="detail.reviewComment" class="info-note">SQE意见：{{detail.reviewComment}}</p>
<div class="quality-grid"><div v-for="f in detail.files" :key="f.id"><button class="text-btn" :disabled="busy" @click="run(()=>download(f.id))">下载 {{f.name}}</button><label v-if="writer&&detail.kind==='SCAR'&&['OPEN','RETURNED','ESCALATED'].includes(detail.status)"><input type="checkbox" v-model="selectedFiles" :value="f.id"/>纳入本次8D</label></div></div>
<template v-if="writer&&['DRAFT','OPEN','RETURNED','ESCALATED'].includes(detail.status)"><label>质量附件<input type="file" accept="application/pdf,image/png,image/jpeg" @change="attachment=$event.target.files[0]"/></label><button class="btn" :disabled="busy||!attachment" @click="run(upload)">上传质量私有附件</button><form @submit.prevent="run(submit)"><template v-if="detail.kind==='PPAP'"><h4>PPAP提交物清单（每项须关联附件）</h4><div v-for="(item,i) in ppapItems" :key="item.fileId" class="quality-actions"><label>提交物名称<input v-model="item.name" required maxlength="128"/></label><button type="button" class="btn" @click="ppapItems.splice(i,1)">移除此提交项</button></div><label>提交说明<textarea v-model="comment" required maxlength="1000"/></label></template><template v-else><label v-for="(name,d) in dnames" :key="d">{{d}} · {{name}}<textarea v-model="disciplines[d]" required maxlength="3000"/></label></template><button class="btn primary" :disabled="busy||(detail.kind==='PPAP'?!ppapItems.length:!selectedFiles.length)">{{detail.kind==='PPAP'?'提交PPAP审核':'提交完整8D回复'}}</button></form></template>
<template v-else><div v-if="detail.payload.items"><h4>本版提交物</h4><p v-for="item in detail.payload.items" :key="item.fileId">{{item.name}}</p></div><div v-if="detail.payload.disciplines"><h4>本版8D回复</h4><p v-for="(value,k) in detail.payload.disciplines" :key="k"><strong>{{k}} {{dnames[k]}}</strong>：{{value}}</p></div></template>
<div v-if="sqe&&detail.status==='SUBMITTED'"><label>SQE审核意见<textarea v-model="comment" maxlength="1000"/></label><div v-for="t in detail.tasks" :key="t.id" class="quality-actions"><button class="btn primary" :disabled="busy||!comment.trim()" @click="run(()=>review(t,'APPROVE'))">审核通过</button><button class="btn" :disabled="busy||!comment.trim()" @click="run(()=>review(t,'RETURN'))">补件／重做</button><button v-if="detail.kind==='PPAP'" class="btn" :disabled="busy||!comment.trim()" @click="run(()=>review(t,'REJECT'))">驳回PPAP</button></div></div>
<form v-if="sqe&&detail.status==='VERIFIED'" @submit.prevent="run(close)"><label>措施有效性验证结果<textarea v-model="effectiveness" required maxlength="2000"/></label><label>有效性证据引用<input v-model="evidence" required maxlength="500"/></label><button class="btn primary" :disabled="busy">确认有效性并闭环SCAR</button></form>
<details><summary>版本与操作历史</summary><p v-for="r in detail.revisions" :key="r.revision">第{{r.revision}}版 · {{text(r.status)}} · {{r.createdAt}}</p><p v-for="(h,i) in detail.history" :key="i">{{h.action}} · {{h.content.comment||h.content.effectiveness||''}} · {{h.createdAt}}</p></details></article>
<article v-if="risk" class="quality-card"><h3>{{text(risk.riskType)}} · {{text(risk.status)}} · <b :class="['risk-light',risk.level]">{{text(risk.level)||'待评估'}}</b></h3><p>来源：INTERNAL · 只归集内部事件和有证据的人工登记</p><p v-if="risk.basis.description">事实：{{risk.basis.description}}</p><p v-if="risk.basis.evidenceRef">证据：{{risk.basis.evidenceRef}}</p><p v-if="risk.basis.basis">履约依据：{{risk.basis.kind}} · 单据 {{risk.basis.poId}} · {{risk.basis.basis.dueDate||''}} {{risk.basis.basis.tolerancePct?('容差 '+risk.basis.basis.tolerancePct+'%'):''}}</p><p v-if="risk.basis.certificateId">资质 {{risk.basis.certType}} · 有效期至 {{risk.basis.validTo}}</p><p v-if="risk.basis.scarId">SCAR {{risk.basis.scarId}} · 重复次数 {{risk.basis.repeatCount}}</p><p v-if="risk.assessment">已评估说明：{{risk.assessment}}</p><form v-if="sqe&&risk.status!=='DISPOSED'" @submit.prevent="run(assess)"><label>风险等级<select aria-label="风险等级" v-model="riskLevel"><option value="HIGH">高（生成经理冻结建议待办）</option><option value="MEDIUM">中</option><option value="LOW">低</option></select></label><label>评估／处置意见<textarea v-model="assessment" required maxlength="2000"/></label><button class="btn" :disabled="busy">保存风险评估</button></form><p v-if="risk.freezeSuggested" class="info-note">高风险冻结建议{{risk.freezeApprovalId?'已进入审批：'+risk.freezeApprovalId:'待采购经理处理'}}。供应商状态只由原审批流程变更。</p><button v-if="manager&&risk.level==='HIGH'&&!risk.freezeApprovalId&&risk.status!=='DISPOSED'" class="btn" :disabled="busy||!assessment.trim()" @click="run(freeze)">将冻结建议提交经理审批</button><form v-if="sqe&&risk.level&&risk.status!=='DISPOSED'" @submit.prevent="run(dispose)"><label>处置结果<select aria-label="处置结果" v-model="disposition"><option value="RECTIFIED">整改完成</option><option value="MONITOR">有依据地持续观察</option><option value="APPROVAL_SUBMITTED">已提交冻结审批</option></select></label><label>处置证据引用<input v-model="evidence" required maxlength="500"/></label><button class="btn primary" :disabled="busy||!assessment.trim()">归档处置结果</button></form><h4>处置留痕</h4><p v-for="(h,i) in risk.history" :key="i">{{h.action}} · {{h.content.comment}} · {{h.createdAt}}</p><button class="btn" @click="risk=null">关闭风险详情</button></article>
<template v-if="tab==='tasks'"><p v-if="!tasks.length" class="empty-state">暂无当前用户可审核的质量任务；提交者不可自审。</p><div v-for="t in tasks" :key="t.id" class="quality-actions"><span>{{t.kind}} · {{t.title}}</span><button class="btn" :disabled="busy" @click="run(()=>openCase(t.caseId))">核查质量资料</button></div></template>
<template v-if="tab==='sources'"><p class="info-note">本机QMS／ERP沙箱用于契约验证。真实厂商接口和真实数据复验仍待联调；来源缺失不会自动给满分。</p><label>筛选供应商<input v-model="candidateSearch" placeholder="供应商名称或编号"/></label><button class="btn" :disabled="busy" @click="run(candidates)">查询质量供应商</button><div class="quality-grid"><label>来源供应商<select aria-label="来源供应商" v-model="source.supplierId"><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>绩效月份<input type="month" v-model="source.period"/></label><label>来源模式<select aria-label="来源模式" v-model="source.mode"><option value="SANDBOX">本机沙箱</option><option value="LIVE">真实接口</option></select></label><label>检验结论<select aria-label="检验结论" v-model="source.result"><option value="FAIL">不合格</option><option value="PASS">合格</option></select></label><label>不合格严重度<select aria-label="不合格严重度" v-model="source.severity"><option value="MINOR">轻微</option><option value="MAJOR">主要</option><option value="SEVERE">严重</option></select></label></div><div class="quality-actions"><button v-if="source.mode==='SANDBOX'" class="btn" :disabled="busy" @click="run(()=>demo('ERP'))">模拟ERP绩效基础项</button><button v-if="source.mode==='SANDBOX'" class="btn" :disabled="busy" @click="run(()=>demo('QMS'))">模拟QMS签名检验回写</button><button class="btn" :disabled="busy" @click="run(sourcePreview)">预览来源与扣分</button></div><article v-if="preview" class="quality-card"><h3>{{preview.mode==='SANDBOX'?'本机沙箱':'真实接口'}} · {{preview.period}}</h3><p v-if="!preview.ready">{{preview.notice}}</p><template v-else><p>交付 {{preview.scores[0]}} · 质量 {{preview.scores[1]}} · 成本 {{preview.scores[2]}} · 服务 {{preview.scores[3]}}</p><p>质量分 = max(0, 100 − 当前有效检验扣分合计)；其余分项来自签名ERP基础数据。</p><button class="btn primary" :disabled="busy" @click="run(publish)">按当前来源发布并重算绩效</button></template><div class="table-scroll"><table><thead><tr><th>检验引用</th><th>来源版本</th><th>结论</th><th>严重度</th><th>扣分</th><th>规则版本</th></tr></thead><tbody><tr v-for="r in preview.inspections" :key="r.ID"><td>{{r.ID}}</td><td>{{r.SOURCE_VERSION}}</td><td>{{r.RESULT==='PASS'?'合格':'不合格'}}</td><td>{{text(r.SEVERITY)}}</td><td>{{r.DEDUCTION}}</td><td>{{r.POLICY_VERSION}}</td></tr></tbody></table></div></article></template>
<form v-if="tab==='policy'&&policy" class="quality-card" @submit.prevent="run(savePolicy)"><h3>质量规则 · 版本 {{policy.version}}</h3><div class="quality-grid"><label>8D回复期限（天）<input type="number" min="1" max="365" v-model.number="policy.responseDays" required/></label><label>重复缺陷窗口（天）<input type="number" min="1" max="365" v-model.number="policy.repeatWindowDays" required/></label><label>轻微不合格扣分<input type="number" min="0" max="100" step="0.01" v-model.number="policy.minorDeduction" required/></label><label>主要不合格扣分<input type="number" min="0" max="100" step="0.01" v-model.number="policy.majorDeduction" required/></label><label>严重不合格扣分<input type="number" min="0" max="100" step="0.01" v-model.number="policy.severeDeduction" required/></label></div><label>变更依据<input v-model="policy.reason" maxlength="500" required/></label><button v-if="manager" class="btn primary" :disabled="busy">发布质量规则新版本</button></form>
<template v-if="tab==='notices'"><p v-if="!notices.length" class="empty-state">暂无质量通知</p><article v-for="n in notices" :key="n.id" class="quality-card"><strong>{{n.message}}</strong><small>{{n.createdAt}} · {{n.businessId}}</small></article></template>
<div v-if="['PPAP','SCAR','risks'].includes(tab)" class="table-footer"><span>共 {{total}} 条</span><button class="btn" :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}}</span><button class="btn" :disabled="busy||page*20>=total" @click="page++;run(load)">下一页</button></div></section></template>
<style scoped>.quality-panel{padding:20px}.quality-card{border:1px solid #dce5e0;border-radius:10px;padding:20px;margin:20px 0}.quality-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:16px 0}.quality-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:14px}.quality-panel label{display:flex;flex-direction:column;gap:6px;margin:12px 0}.quality-panel textarea{width:100%;min-height:75px}.quality-panel small{display:block;color:#6b7870}.risk-light{display:inline-block;padding:4px 8px;background:#edf0ee;color:#536158;border-radius:6px}.risk-light.HIGH{background:#ffe6e5;color:#a12424}.risk-light.MEDIUM{background:#fff0cb;color:#765300}.risk-light.LOW{background:#e6f5e9;color:#216b37}.quality-panel input[type=checkbox]{width:auto}.quality-panel .table-scroll{overflow-x:auto}</style>
